-- Expanded Sandy Sports starter courses.
-- Update only the original unedited drafts. Published versions and officer edits are preserved.

UPDATE learning_course_versions SET
  description='Prepare a prospective Assistant Secretary to share meeting and AGM materials, recover officer work, handle approved communications and help the Secretary maintain membership and handover records.',
  lessons_json=json_array(
    json('{"title":"Agree the prospective deputy remit","body":"Read the actual status of the proposed office and agree what the Secretary can assign now. Identify which tasks you can prepare, which you will handle under documented cover and which require a named approval or restricted role. Check access in the real authorised role before any live use. Keep a joint list of deadlines, unresolved work and the contact to escalate to before taking responsibility for a public notice or member record.\n\nKeep the delegated work, authority, backup contact and review date in the authorised record.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the delegated work, authority, backup contact and review date using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Someone sees the Assistant Secretary label and asks for an immediate formal approval. What do you check?","choices":[{"id":"a","text":"Approve in the same way as the Secretary because the role name indicates deputy access."},{"id":"b","text":"Check actual authority, delegated scope and the current formation or approval setting."}],"correct_choice_id":"b","explanation":"The operating record needs the delegated work, authority, backup contact and review date. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the delegated work, authority, backup contact and review date"},{"id":"b","text":"the role label and a message that cover has begun"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Prepare meeting papers and support the record","body":"Check papers, draft agenda, circulated versions, relevant notices and nominations with the Secretary. Flag a missing report or changed motion while it is still useful to reschedule or correct. In approved cover, record the actual outcome, attendance and actions and route sensitive working notes appropriately. Review any transcript suggestions against what was agreed before the next version is shared.\n\nKeep the agenda and notice versions, source papers, decision and update owner in the authorised record.","captureNotes":"Walk through Meetings and minutes with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the agenda and notice versions, source papers, decision and update owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"You find an amended agenda after members received the notice. What do you do first?","choices":[{"id":"a","text":"Confirm what was sent and which authorised correction or next process applies."},{"id":"b","text":"Put the amended version on the public calendar so everyone sees the latest file."}],"correct_choice_id":"a","explanation":"The operating record needs the agenda and notice versions, source papers, decision and update owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"an overwritten attachment with no record of recipients"},{"id":"b","text":"the agenda and notice versions, source papers, decision and update owner"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Own internal notices and returned officer work","body":"Check which notices ask for information and which link to a task. Identify affected offices, response owner and due date. Confirm unclear work-list marks with the responsible officer before entering them. Record outcome, outstanding dependency and next reminder or review. Verify that linked work is complete before asking to archive the notice. Print or handle individual lists with their correct audience.\n\nKeep the notice and job references, evidence and named open response in the authorised record.","captureNotes":"Walk through Officer to-do lists with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the notice and job references, evidence and named open response using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An officer ticks an action but the notice has a second response still outstanding. What status is useful?","choices":[{"id":"a","text":"Archive the notice because the first linked task is done."},{"id":"b","text":"Record the part completed, leave the response open, and tell the responsible officer when it is due."}],"correct_choice_id":"b","explanation":"The operating record needs the notice and job references, evidence and named open response. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the notice and job references, evidence and named open response"},{"id":"b","text":"a printed tick with no link to the notice"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Maintain AGM, formation and document preparation","body":"Help locate the current source rules, report drafts, nominations and the latest meeting record. Index documents and labels by version, status, access and owner. Check which deadlines relate to real formation work and which are part of the AGM rehearsal. Build a follow-up list and tell the Secretary about missing authorisations or a late paper before release.\n\nKeep the current versions, review state, responsible office and deadline in the authorised record.","captureNotes":"Walk through AGM preparation and Club documents with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the current versions, review state, responsible office and deadline using invented details. Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A revised finance report arrives without a review marker and the previous version was cleared. What should happen?","choices":[{"id":"a","text":"Index the new version as pending and ask the appropriate reviewer which version can be circulated."},{"id":"b","text":"Replace the older attachment because it is late in the preparation process."}],"correct_choice_id":"a","explanation":"The operating record needs the current versions, review state, responsible office and deadline. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a folder of unlabeled report copies"},{"id":"b","text":"the current versions, review state, responsible office and deadline"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Assemble newsletters and check member delivery","body":"Agree the current issue and contributors with the Secretary. Draft and preview content for its actual audience. Check confirmed event dates, opt-in and optional offers, source links, credit and any review needed. Keep an outbound message in the right stage and verify who can send and record a real delivery. Use the member notice desk for reviewed messaging and file corrections under the correct issue.\n\nKeep the edition, clearance, audience, delivery evidence and follow-up owner in the authorised record.","captureNotes":"Walk through Newsletter and Email awaiting delivery with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the edition, clearance, audience, delivery evidence and follow-up owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A note is marked ready in the email queue. Does that show members received it?","choices":[{"id":"a","text":"Mark it delivered because the reviewer cleared the draft wording."},{"id":"b","text":"Check the actual delivery evidence and record readiness separately."}],"correct_choice_id":"b","explanation":"The operating record needs the edition, clearance, audience, delivery evidence and follow-up owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the edition, clearance, audience, delivery evidence and follow-up owner"},{"id":"b","text":"a draft marked sent when delivery is unverified"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Support membership, packs and youth referrals","body":"Help the Secretary find the correct application or interest record, avoid duplicates, and check which onboarding or pack work is assigned. Ask the Treasurer to confirm any relevant payment or waiver. Route youth permission and safeguarding decisions to the authorised people. Record the status of the applicant or renewal using its purpose and update the authorised register only within your scope. Keep family and consent detail private.\n\nKeep the case stage, requested pack or follow-up and private approval dependency in the authorised record.","captureNotes":"Walk through Membership and volunteer applications with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the case stage, requested pack or follow-up and private approval dependency using invented details. Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A youth application appears in the work queue and you do not have the safeguarding role. What do you do?","choices":[{"id":"a","text":"Refer the appropriate status and record reference to the authorised role and keep personal details restricted."},{"id":"b","text":"Ask the guardian to send all details directly to your own inbox and decide yourself."}],"correct_choice_id":"a","explanation":"The operating record needs the case stage, requested pack or follow-up and private approval dependency. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"personal details copied into a shared officer checklist"},{"id":"b","text":"the case stage, requested pack or follow-up and private approval dependency"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Help check Social Studio and event changes","body":"Check the monthly plan against the source event and notice. Ask the Secretary which entries you can review and which officer can approve and publish. Record returned drafts and public changes, retaining source event and revision. For a late change use the agreed wording from the event lead and verify the approved channels. Watch for confidential material copied into a post.\n\nKeep the plan revision, source event or offer, reviewer and next release check in the authorised record.","captureNotes":"Walk through Social Studio and committee notices with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the plan revision, source event or offer, reviewer and next release check using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A sponsor name appears in a draft but its acknowledgement has not been approved. What should you do?","choices":[{"id":"a","text":"Clear the post if the sponsor supplied a logo."},{"id":"b","text":"Flag the status and ask the authorised officer to check exact wording and audience before release."}],"correct_choice_id":"b","explanation":"The operating record needs the plan revision, source event or offer, reviewer and next release check. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the plan revision, source event or offer, reviewer and next release check"},{"id":"b","text":"a draft post with no attribution or approval trail"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Hand over both recurring work and cover exceptions","body":"Show the next deputy and Secretary the current joint task list, next papers and notices, returned sheets, issue version, delivery and member follow-ups. List restricted referrals by authorised reference. Recheck access and the scope of temporary cover. Leave named owners and dates for unresolved work and arrange a short first-week walkthrough.\n\nKeep the dated joint list, running documents, referral owners, cover and next check in the authorised record.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the dated joint list, running documents, referral owners, cover and next check using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An incoming deputy can see officer work but a restricted case remains with the Secretary. What should you transfer?","choices":[{"id":"a","text":"The next action and responsible role through authorised means, with access limited to their approved scope."},{"id":"b","text":"Copy the full case into the general handover so both can access it."}],"correct_choice_id":"a","explanation":"The operating record needs the dated joint list, running documents, referral owners, cover and next check. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a broad instruction to cover the role without deadlines"},{"id":"b","text":"the dated joint list, running documents, referral owners, cover and next check"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Create a fictional shared secretarial handover covering a meeting paper change, actions from minutes, a linked notice and returned job sheet, AGM or formation dependencies, newsletter review, a queued message and a membership or safety referral. Show the approved scope, restricted record references, owner and next date for each. Pass when the Secretary can reproduce the current version, confirm what may be done under cover and identify what still needs a decision.',
  edit_version=edit_version+1
WHERE course_id='sandy-assistant-secretary' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Prepare a prospective committee member to take authorised work, participate in decisions, oversee project dependencies, protect records and hand over outcomes.',
  lessons_json=json_array(
    json('{"title":"Understand the prospective role and decision limits","body":"Confirm the status of the club and your proposed role. Read the current rules or draft, shared officer responsibilities and actual delegated work before speaking or committing for the group. Check which responsibilities are collective and which belong to the operator, Secretary, Treasurer or safeguarding lead. Use the individual role and authorised tools assigned.\n\nKeep the office scope, referral contact, decision source and next action in the authorised record.","captureNotes":"Walk through Committee room and Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the office scope, referral contact, decision source and next action using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A committee planning note asks you to promise a refund to an applicant. What do you check?","choices":[{"id":"a","text":"Who holds the authority and payment record and whether the proposed action has been approved."},{"id":"b","text":"Whether the applicant originally contacted you through a private message."}],"correct_choice_id":"a","explanation":"The operating record needs the office scope, referral contact, decision source and next action. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a public note listing who offered to assist"},{"id":"b","text":"the office scope, referral contact, decision source and next action"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Prepare and participate in decisions responsibly","body":"Read the notice, agenda, decision evidence and relevant rules. Declare a relevant interest before discussion or voting and follow the agreed handling. Ask about cost, intended people, actual approvals and who can carry the work. Confirm an accurate decision or note that it remains a proposal. Keep sensitive information inside the authorised audience. Record follow-up in the appropriate desk.\n\nKeep the decision wording, interest handling, limitations and responsible people in the authorised record.","captureNotes":"Walk through Meetings and minutes with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the decision wording, interest handling, limitations and responsible people using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"You are connected to a proposed supplier and the committee asks you to contribute to the choice. What first?","choices":[{"id":"a","text":"Say nothing until someone asks specifically about the supplier relationship."},{"id":"b","text":"Raise the interest using the applicable process before the matter is handled."}],"correct_choice_id":"b","explanation":"The operating record needs the decision wording, interest handling, limitations and responsible people. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the decision wording, interest handling, limitations and responsible people"},{"id":"b","text":"draft notes that show discussion without the authority or declaration"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Own work and provide an evidence-backed update","body":"Take an assigned task or ask the allocator to confirm ownership and due date. Keep a source, actual status and open dependencies. Use the linked notice and work list consistently. Confirm a completed task with evidence before closing what relies on it. Raise late access, cost, safety or staffing questions while the group still has time to address them.\n\nKeep the source, actual work done, open dependencies and owners in the authorised record.","captureNotes":"Walk through Committee notices and Officer to-do lists with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the source, actual work done, open dependencies and owners using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"You finished preparing a draft grant budget but have no quotes yet. What should your update show?","choices":[{"id":"a","text":"Draft complete, quote dependency open and its owner and date."},{"id":"b","text":"The grant budget approved since all draft figures were entered."}],"correct_choice_id":"a","explanation":"The operating record needs the source, actual work done, open dependencies and owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a completion tick without what is still pending"},{"id":"b","text":"the source, actual work done, open dependencies and owners"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Check sport, film and event responsibilities","body":"Find the event lead, venue status, crew, material costs, gear, accessibility, permissions and safeguards. Agree who can change or pause delivery and where a concern is reported. Check role boundaries before volunteering to handle equipment, youth supervision or communications. Use the proper approval route for venue, payments, sponsors, grants or partner work. Record what support you can supply under current authority.\n\nKeep the named role and checks, scope of your task and appropriate referral in the authorised record.","captureNotes":"Walk through Sport, film and community events with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the named role and checks, scope of your task and appropriate referral using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Your event planning task involves handling a private youth form. What do you do?","choices":[{"id":"a","text":"Copy the form into an accessible committee record so it can be discussed generally."},{"id":"b","text":"Send the work to the authorised safeguarding contact without taking over their protected decision."}],"correct_choice_id":"b","explanation":"The operating record needs the named role and checks, scope of your task and appropriate referral. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the named role and checks, scope of your task and appropriate referral"},{"id":"b","text":"a roster with no decision or safety owner"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Review money, records and publication in your scope","body":"Review the evidence behind proposals and ask the Treasurer to confirm amounts, restrictions and approvals. Add only the necessary information to shared records. Check public dates, permissions, approved wording and channel before suggesting a notice or post. Document the release role and where the published result was verified. Flag any error for the lead and responsible publisher.\n\nKeep the funding or publication source, review and status evidence in the authorised record.","captureNotes":"Walk through Grant register and Social Studio with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the funding or publication source, review and status evidence using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A social draft calls a sponsor confirmed before their approval is recorded. What changes?","choices":[{"id":"a","text":"Mark the status accurately and seek clearance for the exact wording."},{"id":"b","text":"Keep the draft and remove only the sponsor logo."}],"correct_choice_id":"a","explanation":"The operating record needs the funding or publication source, review and status evidence. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"a polished announcement with no authorised source"},{"id":"b","text":"the funding or publication source, review and status evidence"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Debrief and hand your work to the next person","body":"Record the result or lessons from the activity, what actually happened, any exception still open and what needs a responsible decision. Provide the current and previous records by authorised reference. Make sure outgoing or incoming access and property are dealt with by the appropriate owners. Agree the next check, especially if the role is still prospective.\n\nKeep a dated handover of decisions, evidence, next owners and restrictions in the authorised record.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include a dated handover of decisions, evidence, next owners and restrictions using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A follow-up is postponed after someone changes roles. What should the outgoing person leave?","choices":[{"id":"a","text":"A general note for the next committee meeting to sort out."},{"id":"b","text":"The named owner or escalation contact, new date and source decision."}],"correct_choice_id":"b","explanation":"The operating record needs a dated handover of decisions, evidence, next owners and restrictions. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a dated handover of decisions, evidence, next owners and restrictions"},{"id":"b","text":"an exported task list with no explanation of outstanding work"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Take a fictional proposed activity from an assigned job through review and handover. Submit a decision brief, disclosure and approval record, sourced cost and venue status, safeguarding or access referral, and a draft update that states the real status. Include a linked task record, debrief and current handover owners. Pass when someone can determine what was decided, what still needs authority and how to carry the work forward.',
  edit_version=edit_version+1
WHERE course_id='sandy-committee-member' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Assess site and equipment options, navigate venue permissions and access, plan setup and maintenance, and transfer assets and operational records.',
  lessons_json=json_array(
    json('{"title":"Establish ownership and the permitted use","body":"Identify the owner, administering contact and current status of each possible site. Ask what site activity, duration, capacity or attachment is allowed and which permissions still apply. Keep public map or concept images distinct from a booking. Record when and by whom the conditions were confirmed and who would make or accept any commitment. Look for conditions relating to restoration, cleanup and renewal.\n\nKeep the site source, responsible authority, allowed use and unresolved decisions in the authorised record.","captureNotes":"Walk through Venue, court and screen bookings with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the site source, responsible authority, allowed use and unresolved decisions using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A council map labels an area open space. What confirms the proposed club activity can go ahead there?","choices":[{"id":"a","text":"The site''s public access on the map and a suitable rough layout."},{"id":"b","text":"The responsible site authority and documented use conditions for the intended event."}],"correct_choice_id":"b","explanation":"The operating record needs the site source, responsible authority, allowed use and unresolved decisions. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the site source, responsible authority, allowed use and unresolved decisions"},{"id":"b","text":"a map marker labelled confirmed venue"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Compare access, layout and programme demands","body":"Walk both options with the sport and film leads. Record approach, accessible arrival, seating or viewing sightlines, amenities, circulation, setup and exit routes and space needed for sport or a screen. Consider weather exposure, noise, transport and neighbouring users. Escalate specialist checks to the relevant site or qualified people. Compare backing options with costs and permission status before recommending one.\n\nKeep the observed conditions, accessibility checks, options and decision owners in the authorised record.","captureNotes":"Walk through Space planner and Venue bookings with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the observed conditions, accessibility checks, options and decision owners using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A site is large enough but has a difficult approach for part of the audience. What goes into the comparison?","choices":[{"id":"a","text":"Record the actual barrier, possible alternative and accountable check before concluding suitability."},{"id":"b","text":"Pass the site because the planned activity fits its footprint."}],"correct_choice_id":"a","explanation":"The operating record needs the observed conditions, accessibility checks, options and decision owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a layout drawing with no on-site or access evidence"},{"id":"b","text":"the observed conditions, accessibility checks, options and decision owners"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Control asset purchases, loans and storage","body":"Record what is offered or purchased, actual ownership, inventory reference, quantity, condition and custody. Verify times and constraints for borrowing, return and maintenance. Confirm spending, quotes, grant restrictions and insurance with the authorised lead and Treasurer. Identify storage conditions and who checks stock between events. Decide who records a fault or an overdue return.\n\nKeep the ownership or loan terms, recorded condition, costs and custody in the authorised record.","captureNotes":"Walk through Club assets and loans with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the ownership or loan terms, recorded condition, costs and custody using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A donor wants the club to keep gear but terms and ownership are unclear. What should be entered?","choices":[{"id":"a","text":"A permanent club asset because the equipment has already been offered."},{"id":"b","text":"An offer with ownership and custody pending the documented agreement."}],"correct_choice_id":"b","explanation":"The operating record needs the ownership or loan terms, recorded condition, costs and custody. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the ownership or loan terms, recorded condition, costs and custody"},{"id":"b","text":"a wishlist item marked owned with no acceptance"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Prepare safe setup and contingency","body":"Agree setup area, timing, roles, gear condition and the site lead’s confirmation. Brief access control, public movement, weather and first response. Record power, structures or other specialist checks with the responsible qualified party rather than signing them off outside your remit. Work with programme leads to confirm the decision to pause or change. Keep site conditions and contingency accessible to rostered staff.\n\nKeep the responsible setup checks, conditions and authorised readiness or hold decision in the authorised record.","captureNotes":"Walk through Sport, film and community events with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the responsible setup checks, conditions and authorised readiness or hold decision using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A temporary structure or power arrangement has a known concern and no authorised specialist check. What should you do?","choices":[{"id":"a","text":"Hold that element, refer it to the responsible person and use only an agreed alternative."},{"id":"b","text":"Proceed with a staff visual check and record the concern later."}],"correct_choice_id":"a","explanation":"The operating record needs the responsible setup checks, conditions and authorised readiness or hold decision. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"a checklist marked complete by whoever was present"},{"id":"b","text":"the responsible setup checks, conditions and authorised readiness or hold decision"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Maintain property and close use","body":"Log equipment return and damage, disposal or repair decisions, site cleanup and condition after use. Route insurance, costs and any access-related concern through the responsible officers and site owner. Preserve the evidence required by any agreement. Keep a maintenance and replacement forecast and confirm who checks faults before the equipment or venue is allocated again.\n\nKeep the post-use check, faults, ownership and next inspection or cost action in the authorised record.","captureNotes":"Walk through Club assets and loans with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the post-use check, faults, ownership and next inspection or cost action using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An asset is returned after a fault that affects the next event. What gets handed over?","choices":[{"id":"a","text":"The return date only because inspection can wait until the next booking."},{"id":"b","text":"The fault and status, responsible check and conditions for reuse or replacement."}],"correct_choice_id":"b","explanation":"The operating record needs the post-use check, faults, ownership and next inspection or cost action. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the post-use check, faults, ownership and next inspection or cost action"},{"id":"b","text":"a count of items returned with no condition check"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Hand over facilities readiness and risks","body":"Give the next lead the latest confirmed site permissions, draft options, calendar, gear register and owners, costs, maintenance, unsafe or held items and due dates. Show how to check conditions with site owners and who holds equipment custody. Review staff access and transfer of keys through authorised processes. Agree next decision and post-event review dates.\n\nKeep the facilities index, actual authorities, equipment and open checks with owners in the authorised record.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the facilities index, actual authorities, equipment and open checks with owners using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The incoming facilities lead gets the floor plan but lacks the accepted site conditions. What do you do?","choices":[{"id":"a","text":"Keep the handover item open and name who will obtain the current authority and use restrictions."},{"id":"b","text":"Use the designer’s plan as the basis to schedule site use."}],"correct_choice_id":"a","explanation":"The operating record needs the facilities index, actual authorities, equipment and open checks with owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a map pack and calendar with approvals inferred"},{"id":"b","text":"the facilities index, actual authorities, equipment and open checks with owners"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Compare two fictional sites for sport and screening. Provide site authority and status, access and layout evidence, equipment inventory or loan conditions, costs and approvals, contingency and accessibility, plus a maintenance, repair and handover record. Rehearse a site or equipment fault. Pass when the recommendation separates research from actual consent and gives each risk, asset and outstanding decision a responsible owner.',
  edit_version=edit_version+1
WHERE course_id='sandy-facilities-lead' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Plan a film workshop or screening from purpose, rights and venue through production, audience access, show checks, release and gear handover.',
  lessons_json=json_array(
    json('{"title":"Scope the film activity and authorise the next step","body":"Describe the audience and aim and choose whether it is a screening, workshop or production. Agree the deliverable, likely space, gear, crew, cost and responsible leads. Identify which permissions, funding and date decisions are still needed. Keep the project listed at the status actually agreed and coordinate with sports, facilities and partners before promising capacity.\n\nKeep the event scope, people, budget assumptions and open authority in the authorised record.","captureNotes":"Walk through Film club and media programme with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the event scope, people, budget assumptions and open authority using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The team has a venue concept and a popular film in mind. What does the lead record?","choices":[{"id":"a","text":"A proposed format and pending venue, rights, budget and crew decisions."},{"id":"b","text":"A planned public screening ready to advertise while checks continue."}],"correct_choice_id":"a","explanation":"The operating record needs the event scope, people, budget assumptions and open authority. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a film title and draft event graphic"},{"id":"b","text":"the event scope, people, budget assumptions and open authority"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Check screening rights, recording permissions and credits","body":"Identify who can approve the film or other material for the proposed audience, platform and use. Separate permission to screen, capture, edit, use music, distribute and share a participant’s image. Check any child or cultural material with the appropriate authorised people. Log credits, scope, restrictions and clearance and brief the crew on what they can use. Hold any unconfirmed items for review.\n\nKeep the permission and use register, responsible decision-makers and holds in the authorised record.","captureNotes":"Walk through Film club and media programme with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the permission and use register, responsible decision-makers and holds using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A filmmaker gives permission for one venue screening and someone wants to post the cut online. What is needed?","choices":[{"id":"a","text":"Use the screening approval because the video file and credits are unchanged."},{"id":"b","text":"Confirm the extra scope with the relevant rights holders and record it before release."}],"correct_choice_id":"b","explanation":"The operating record needs the permission and use register, responsible decision-makers and holds. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the permission and use register, responsible decision-makers and holds"},{"id":"b","text":"a single cleared check covering every possible use"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Coordinate people, venue and the run of show","body":"Agree the venue conditions, capacity, access instructions, opening and closing, audience welcome, accessible viewing and who controls changes. Assign sound, projection, registration and pack-down to people who can cover the schedule. Check permissions and safeguarding arrangements with the relevant lead. Agree the setup and handover times, backup for a missing role and who can pause a programme.\n\nKeep the venue conditions, cue sheet, owners, backups and stop contact in the authorised record.","captureNotes":"Walk through Venue, court and screen bookings with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the venue conditions, cue sheet, owners, backups and stop contact using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"One person is assigned to welcome and projection during doors open. What should the lead do?","choices":[{"id":"a","text":"Reassign or stagger duties and test that the critical jobs have coverage."},{"id":"b","text":"Keep the roles together and trust the crew member will move quickly."}],"correct_choice_id":"a","explanation":"The operating record needs the venue conditions, cue sheet, owners, backups and stop contact. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"a guest schedule with no crew assignments"},{"id":"b","text":"the venue conditions, cue sheet, owners, backups and stop contact"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Test production, captions and playback","body":"Before welcoming people, check the actual file and version, visible pictures, sound level, captions and audience sightlines. For a workshop test the equipment, supervision, permitted shots and transfer path. Agree safe gear handling and route an equipment or power issue through the responsible qualified person where required. Rehearse an alternative or pause if sound, projector, weather or accessibility changes. Record which test passed and who repeats it.\n\nKeep the checked version, observed playback, equipment exceptions and readiness decision in the authorised record.","captureNotes":"Walk through Film club and media programme with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the checked version, observed playback, equipment exceptions and readiness decision using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The file opens on a laptop but the actual show has unreadable captions on the venue screen. What must happen?","choices":[{"id":"a","text":"Keep the checked laptop file and assume it will be readable from most seats."},{"id":"b","text":"Adjust or replace the file and verify captions on the actual equipment before calling it ready."}],"correct_choice_id":"b","explanation":"The operating record needs the checked version, observed playback, equipment exceptions and readiness decision. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the checked version, observed playback, equipment exceptions and readiness decision"},{"id":"b","text":"a record that the film file downloaded successfully"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Control expenses, sponsors and event comms","body":"Confirm quotes, hire and condition records, cancellation terms, approved spending and custody with the Treasurer and facilities lead. Check what contributors have agreed about credits and sponsor acknowledgement. Ask the responsible officers to approve and verify public messaging. Use one authorised update after a changed time or venue and record which channels were checked.\n\nKeep the approved hire or loan, wording, release channels and changes in the authorised record.","captureNotes":"Walk through Sport, film and community events with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the approved hire or loan, wording, release channels and changes using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A supporter provides gear and requests a new public credit just before release. What do you do?","choices":[{"id":"a","text":"Check the exact terms and approved wording before changing the release."},{"id":"b","text":"Add the wider acknowledgement to every channel because gear was lent."}],"correct_choice_id":"a","explanation":"The operating record needs the approved hire or loan, wording, release channels and changes. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"purchase estimates and a logo without actual permission"},{"id":"b","text":"the approved hire or loan, wording, release channels and changes"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Close screenings or production and hand over","body":"Check the actual deliverable, return and condition of gear, authorised files and backups, rights and retention, incident or complaint route, costs, attendance and feedback. Log which final export was approved and which copy belonged to the rehearsal. Give the next lead the source versions, partner and venue commitments, outstanding rights or claims and review date.\n\nKeep the final version, gear custody, rights, costs and unresolved action references in the authorised record.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the final version, gear custody, rights, costs and unresolved action references using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The final folder contains a rough cut and a reviewed cut. What does the successor need?","choices":[{"id":"a","text":"Send the newest export and rely on the file date to indicate approval."},{"id":"b","text":"Identify the reviewed version and its use conditions, plus any outstanding changes and owner."}],"correct_choice_id":"b","explanation":"The operating record needs the final version, gear custody, rights, costs and unresolved action references. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the final version, gear custody, rights, costs and unresolved action references"},{"id":"b","text":"an archive with loose exports and no status"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Build a fictional screening or film workshop pack. Include format and scope, venue and screening or participant permissions, a cue sheet and roster, sound and caption checks, approvals for one paid or hired item, a plan for a failure or weather change, and release and gear handover. Pass when the duty owners can set up and pause the event, all intended uses have reviewed authority, and any open permission or equipment issue is easy to find.',
  edit_version=edit_version+1
WHERE course_id='sandy-film-lead' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Choose whether to watch, help at a screening or learn behind the scenes.',
  lessons_json=json_array(
    json('{"title":"Choose how you want to take part","body":"Explore the film club and proposed screenings. Ask whether a session is for an audience, a workshop crew or people learning a particular task.","captureNotes":"Show a public film club concept and fictional workshop listing. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Prepare for your first session","body":"Confirm the venue, timing, lead and what to bring. If you want to record or appear in footage, ask about notices, permissions and sharing before capturing or posting."}'),
    json('{"title":"Prepare for the correct session","body":"Confirm whether you have a place as an audience member, workshop learner, performer or crew helper and what equipment or access support is available. Ask who is responsible for the venue, arrival and changed arrangements. Treat concept dates as proposed until confirmed.","captureNotes":"Walk through Film Club and programme with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Agree filming and use","body":"Ask how taking part, being filmed and sharing a clip will be handled. Confirm the intended audience and where the approved material may be used, particularly for a young participant or a contributor who has set restrictions. Check before publishing or taking home footage.","captureNotes":"Walk through Film Club contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Finish the session and choose a next step","body":"Return equipment, share feedback and ask what may be kept or used in a portfolio. Confirm who receives a concern, how lost items are recorded and how to hear about the next proposed workshop or screening.","captureNotes":"Walk through Film Club workshop or screening lead with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='sandy-film-participant' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Follow the club''s formation, find your prospective member area and offer a practical contribution.',
  lessons_json=json_array(
    json('{"title":"Find your starting point","body":"Open Join and My Membership. Use the current instructions for expressing interest or using any joining option the operator has made available. The preview lets you see how the area works using fictional information.","captureNotes":"Show the public Join page and labelled My Membership preview. Use fictional names and no sign-up details. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Bring one founding idea","body":"Offer a skill, time or idea for sport, film or facilities. Ask how input on the club purpose, proposed rules and first activities is collected. Confirm what the operator has actually agreed before representing the club to others."}'),
    json('{"title":"Understand the current offer and decisions","body":"Use the actual form or current joining option and follow its stated terms. Check which arrangements are still in formation and where input on purpose, classes or rules is collected. Keep a website account or expression of interest distinct from any later authority to represent the club.","captureNotes":"Walk through Join and My Membership with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Put forward a workable contribution","body":"Offer a specific time, skill, asset or idea and note any conditions and who would have to agree. Use the suggested sport, film, facilities or supporter route to ask what the proposed work needs. Agree the status before telling other people you are committed.","captureNotes":"Walk through Founding discussions and programme with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Review proposals and communications","body":"Check current rules, proposals, dates and approved statements before forwarding them. Ask where to correct your details or change contact preferences. Keep private names and access links within the agreed workflow and raise unclear decisions with the organiser.","captureNotes":"Walk through Constitution and project contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='sandy-founding-member' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Help a young person and guardian ask the right questions about proposed sessions.',
  lessons_json=json_array(
    json('{"title":"Choose a session together","body":"Look for the proposed age group, activity and experience level. Ask the responsible contact how supervision, check-in and pickup would be organised before agreeing to take part.","captureNotes":"Use fictional family details and only public proposed session pages. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Check safeguarding and sharing","body":"Ask who handles safety and how to raise a concern. Discuss photo, video and online sharing separately so the guardian and young person understand the choice."}'),
    json('{"title":"Check participation and pickup","body":"The guardian checks the actual age range, site and supervision, the check-in and pickup arrangements, and who can help with accessibility or equipment. If plans change, contact the organiser and agree who will collect the young person.","captureNotes":"Walk through Public activity page and session lead with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Understand permission choices","body":"Ask which choices relate to joining an activity, photographs or films and online sharing. Ask how a young person can raise a concern or request a different arrangement and who supervises the activity. Use a private authorised route for personal information.","captureNotes":"Walk through Join and youth contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Know what to do during and after the activity","body":"Tell the lead if you need help or a break, do not know how to use equipment or are unsure who should collect you. Ask the guardian and lead about future sessions and what sharing, results or group messages were approved.","captureNotes":"Walk through Programme and event lead with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='sandy-junior-member' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Explore participation from off-island and check event access before making plans.',
  lessons_json=json_array(
    json('{"title":"Find a suitable activity","body":"Look for proposed sessions and the event contact. Ask about availability, timings and who would be able to take part. Check your own travel plans separately.","captureNotes":"Capture the public places and programme pages. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Offer a realistic commitment","body":"Share how often you could take part and what support or skills you can offer. Ask which membership and activity arrangements are being considered for people who live off-island."}'),
    json('{"title":"Plan the trip around confirmed details","body":"Check the organiser’s confirmation, venue, participation options and last update before travel. Check your own transport and accessibility arrangements and ask who will send a change. Keep a proposed site or date distinct from a reservation.","captureNotes":"Walk through Places and Programme with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Agree an off-island commitment","body":"Describe your actual availability, contribution, travel constraints and what help you need. Ask how the proposed membership class or casual participation will be decided and what details the project actually needs. Confirm costs before accepting a commitment.","captureNotes":"Walk through Public interest route with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Handle changes and keep in contact","body":"Find the route for cancellation, substitution, equipment return and feedback. Keep your account and contact preferences current if you are using an authorised member route. Work with the organiser before sharing any assumed date or member benefit.","captureNotes":"Walk through Activity contact and My Membership with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='sandy-non-resident-member' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Prepare the proposed President to chair formation decisions, coordinate the prospective committee, oversee risks and responsibilities, and run a checked transition.',
  lessons_json=json_array(
    json('{"title":"Establish formation status and authority","body":"Start with the proposal, current operator and actual formation evidence. Check draft rules, likely roles, decision powers and which existing organisation or site owner can agree a commitment. A reserved officer seat and the website’s committee desks support preparation. Record which matters the planning group can agree and which must wait for the proper authority. Use current Fair Trading guidance for incorporation steps and have the responsible person verify any planned filing.\n\nKeep the proposal and authority references, owner and open confirmation steps in the authorised record.","captureNotes":"Walk through Governance and decisions with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the proposal and authority references, owner and open confirmation steps using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A prospective sponsor asks for a signed commitment from the proposed President. What needs checking?","choices":[{"id":"a","text":"The name on the website’s reserved officer account and whether the sponsor deadline is near."},{"id":"b","text":"Who can lawfully sign now, what the proposal permits and what decision or confirmation is still needed."}],"correct_choice_id":"b","explanation":"The operating record needs the proposal and authority references, owner and open confirmation steps. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the proposal and authority references, owner and open confirmation steps"},{"id":"b","text":"a role badge and sponsor request with no evidence"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Prepare meetings and handle conflicts","body":"Agree the purpose, notice, papers, eligible participants and current status of each item with the Secretary. Chair a fictional meeting using the relevant adopted or proposed rules explicitly for its status. Record interests, how participation changes, quorum and the outcome of each item. If the authority or rule is unclear, record the reason to defer. Ask the Secretary to read back the agreed wording, owners and deadlines. Separate decisions on planning from future formal votes.\n\nKeep the meeting basis, disclosures, wording and action owner, with draft or formal status in the authorised record.","captureNotes":"Walk through Meetings and minutes with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the meeting basis, disclosures, wording and action owner, with draft or formal status using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A group discusses a proposed rule and appears to agree informally. How do you record it?","choices":[{"id":"a","text":"Record the discussion and any agreed planning action, and identify the proper process for adopting rules."},{"id":"b","text":"Mark the rule adopted because none of the people present objected."}],"correct_choice_id":"a","explanation":"The operating record needs the meeting basis, disclosures, wording and action owner, with draft or formal status. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a list of ideas labelled resolutions by the chair"},{"id":"b","text":"the meeting basis, disclosures, wording and action owner, with draft or formal status"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Organise the proposed officer team and AGM preparation","body":"Check which prospective offices and working groups have an agreed person, a backup and a defined task. Use Officer to-do lists for overdue dependencies. Use the AGM desk to rehearse nominations, voting, reports and changeover under eventual rules. Make clear which notices, filings and appointments belong to formation now and which would be future obligations. Agree the succession walkthrough for an office with no backup.\n\nKeep the prospective roles, backup, actual decision, records and appointment dependencies in the authorised record.","captureNotes":"Walk through AGM preparation with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the prospective roles, backup, actual decision, records and appointment dependencies using invented details. Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A person is willing to cover a desk and asks to be named as elected. What is the correct record?","choices":[{"id":"a","text":"List them as elected so they can perform the handover confidently."},{"id":"b","text":"Record their proposed scope and any approved present work, pending the valid appointment process."}],"correct_choice_id":"b","explanation":"The operating record needs the prospective roles, backup, actual decision, records and appointment dependencies. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the prospective roles, backup, actual decision, records and appointment dependencies"},{"id":"b","text":"a list of names without decision dates or role status"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Oversee sports, film, facilities and safeguarding","body":"Ask the leads to bring a clear plan for the venue, dates, equipment, crew, accessible and inclusive participation, permissions, safeguarding and any required checks. Compare status across the sport, film and venue desks before accepting a date. Confirm who can stop or change an activity and who handles a concern privately. Check current Queensland child-safe and Blue Card guidance with the responsible safeguarding lead. Use an incident reference in committee oversight without spreading confidential details.\n\nKeep the site and event decision, safeguarding confirmation reference and go or pause owner in the authorised record.","captureNotes":"Walk through Sport, film and community events with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the site and event decision, safeguarding confirmation reference and go or pause owner using invented details. Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A proposed junior event has a roster but the safety lead has not confirmed checks. What is the chair’s role?","choices":[{"id":"a","text":"Leave that event status open and obtain the required checks and authorised safety decision."},{"id":"b","text":"Treat the roster as enough and ask volunteers to resolve checks on the day."}],"correct_choice_id":"a","explanation":"The operating record needs the site and event decision, safeguarding confirmation reference and go or pause owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"an activity date and attendance estimate with no check record"},{"id":"b","text":"the site and event decision, safeguarding confirmation reference and go or pause owner"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Review budgets, fundraising, grants and partnerships","body":"Get the Treasurer’s costs, restricted funding, cash commitments, recurring costs and major uncertainties. Ask who can authorise spending, sign an application or accept a venue or sponsor offer. Record membership and fee discussion with its proposed status. For partner work, confirm authority, scope, tasks retained, costs, written acceptance and review date. Use separate records for each organisation and give a useful explanation to the committee.\n\nKeep the authorised scope, funding or asset conditions, public wording and review date in the authorised record.","captureNotes":"Walk through Grant register with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the authorised scope, funding or asset conditions, public wording and review date using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A partner offers equipment and asks to be announced in return. What must be resolved?","choices":[{"id":"a","text":"Announce a confirmed partner to help the group secure the equipment."},{"id":"b","text":"Agree the offer scope, custody terms and exact authorised acknowledgement before confirmation."}],"correct_choice_id":"b","explanation":"The operating record needs the authorised scope, funding or asset conditions, public wording and review date. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the authorised scope, funding or asset conditions, public wording and review date"},{"id":"b","text":"an offer email and a logo added to the draft site"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Maintain communications and respond to exceptions","body":"Use the notices desk for internal work and confirm what can be shared publicly. Review dates, proposed versus confirmed status, venue authority, participant permissions and who can release an update. For a cancellation, obtain the lead’s instruction and check the change across affected channels. Record corrections and unresolved risks. Give the Secretary the approved wording and reference rather than bypassing their publication process.\n\nKeep the checked source, cleared public wording, affected channels, owner and correction time in the authorised record.","captureNotes":"Walk through Committee notices and Social Studio with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the checked source, cleared public wording, affected channels, owner and correction time using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The club’s public calendar and a post show different dates. What belongs in your correction?","choices":[{"id":"a","text":"Confirm the current source and release owner, then verify the corrected affected channels."},{"id":"b","text":"Publish a third date in a comment while leaving the older copies in place."}],"correct_choice_id":"a","explanation":"The operating record needs the checked source, cleared public wording, affected channels, owner and correction time. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"an unverified social comment without a public change record"},{"id":"b","text":"the checked source, cleared public wording, affected channels, owner and correction time"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Hand over priorities, decisions and authority","body":"Bring the current formation status, draft rules version, upcoming agenda, decisions and unfinished actions, venue and funds status, confidential routes and communications awaiting approval. Give each gap an owner and review date. Confirm individual access changes with the Webmaster and demonstrate how to verify one decision from source to follow-up. Agree the first-week review and record which responsibilities remain with the operator or other people.\n\nKeep a dated handover with approved and proposed authority, records and named next actions in the authorised record.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include a dated handover with approved and proposed authority, records and named next actions using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An incoming chair has the dashboard but can''t find the current rules version. What do you do?","choices":[{"id":"a","text":"Tell them to use any version in the constitution builder until an AGM is held."},{"id":"b","text":"Identify the agreed source and version, assign resolution of the gap and keep the handover follow-up open."}],"correct_choice_id":"b","explanation":"The operating record needs a dated handover with approved and proposed authority, records and named next actions. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a dated handover with approved and proposed authority, records and named next actions"},{"id":"b","text":"a sign-in confirmation and an undated list of files"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Chair a fictional founding discussion, then prepare the decision and handover pack for a proposed sports and film trial. Include proposed versus agreed authority, rules and notice check, a disclosure and quorum case, the actual wording and follow-up of a decision, venue and funding dependencies, safeguarding and an approved communications route. Identify when a formal decision would become available. Pass when each unresolved dependency stays visible and no draft authority is treated as a commitment.',
  edit_version=edit_version+1
WHERE course_id='sandy-president' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Explore the proposed local adult membership option and say what should be available locally.',
  lessons_json=json_array(
    json('{"title":"Find the local activities","body":"Compare planned activities in Dunwich, Amity Point and Point Lookout. Ask what is being proposed, who is organising it and how to hear about a confirmed trial.","captureNotes":"Show the public programme and activity information. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Shape what membership could mean","body":"Use the interest route to share one activity and one contribution you could make. Ask about proposed responsibilities and how the founding group will decide fees or participation."}'),
    json('{"title":"Compare activity and membership choices","body":"Ask which local sport, film or volunteer activities are proposed and which actually have an organiser and confirmed arrangements. Check what the current membership route offers and when rules, fees or event arrangements are still open to input.","captureNotes":"Walk through Programme, Join and My Membership with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Attend or help through a confirmed lead","body":"Check the venue and latest update, equipment, costs, accessibility and who handles a request for a change. If you help, confirm the time, duty and lead and report unsafe or unclear arrangements through the designated contact.","captureNotes":"Walk through Event and places information with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Have a say and manage your details","body":"Offer specific ideas based on local needs, attend agreed discussions and ask how proposals are recorded and decided. Use the approved way to check or correct your contact choices. Ask before sharing other people’s images, messages or membership details.","captureNotes":"Walk through Founding invitation and member contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='sandy-resident-member' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Maintain the formation record, run meeting and AGM preparation, trace membership and notices, and protect the authority and evidence used by successor officers.',
  lessons_json=json_array(
    json('{"title":"Set up the formation record and authority register","body":"Identify the current operator, rules draft, amendment history, nominated people and available evidence of agreed planning work. Use the documents register to index each source, owner, access class and version. Keep actual source files in authorised storage. Mark which legal or membership clarification is pending and use official Fair Trading guidance to check eventual rules and filing responsibilities. Record dates and owners with the prospective Chair and Treasurer.\n\nKeep the source, version, custody, authority and outstanding review in the authorised record.","captureNotes":"Walk through Club documents and register with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the source, version, custody, authority and outstanding review using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A rules draft is changed in the online builder. What should the Secretary record?","choices":[{"id":"a","text":"Replace all earlier versions and mark the new text adopted."},{"id":"b","text":"Index the dated draft and decision route and keep the prior reference available."}],"correct_choice_id":"b","explanation":"The operating record needs the source, version, custody, authority and outstanding review. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the source, version, custody, authority and outstanding review"},{"id":"b","text":"a link titled current constitution with no evidence"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Call a meeting and prepare the notice and papers","body":"Confirm purpose and meeting status, accountable convenor, agenda, date, venue or remote access, papers and audience. Check notice and voting arrangements against the appropriate source for the meeting status. Document what was sent and when. Flag late items, uncertain nominations and missing reports so the Chair can decide how to handle them. Keep proposed and confirmed dates separate in public information.\n\nKeep the notice, source and delivery record, venue status and linked agenda version in the authorised record.","captureNotes":"Walk through Meetings and minutes with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the notice, source and delivery record, venue status and linked agenda version using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A notice draft names a venue that is still being discussed. What changes before circulation?","choices":[{"id":"a","text":"Confirm the meeting’s arrangements and record any unresolved location before issuing a proper notice."},{"id":"b","text":"Assume the venue name is safe because it appears in the planning desk."}],"correct_choice_id":"a","explanation":"The operating record needs the notice, source and delivery record, venue status and linked agenda version. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"an agenda attachment with no recipient or notice evidence"},{"id":"b","text":"the notice, source and delivery record, venue status and linked agenda version"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Minute decisions and preserve the approval trail","body":"Keep attendance, quorum where applicable, interest declarations, actual wording, outcomes and follow-up owners in the appropriate record. Label transcript or AI-assisted text as draft and check it against the actual discussion. Clear any use of recordings or processing with the responsible people. Reconcile the final minutes with officer tasks. Use version and history to preserve what was amended, reviewed and released to the right audience.\n\nKeep the corrected draft, actual decision, approval version and resulting actions in the authorised record.","captureNotes":"Walk through Meetings and minutes with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the corrected draft, actual decision, approval version and resulting actions using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A generated minute says the club approved a spend when it only discussed an estimate. What do you record?","choices":[{"id":"a","text":"Accept the draft because the figure and item are otherwise correct."},{"id":"b","text":"Correct the minutes against what happened and retain the decision or proposal status and reviewer."}],"correct_choice_id":"b","explanation":"The operating record needs the corrected draft, actual decision, approval version and resulting actions. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the corrected draft, actual decision, approval version and resulting actions"},{"id":"b","text":"a polished AI summary with no check against the source"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Prepare nominations, AGM and future filings","body":"Build a checklist for nominations, record status, papers, notices, meeting basis, voting, reports and office transition. Use current guidance and the actual rules when statutory steps apply. Track evidence, responsible officers and dates for each item. Keep a future AGM rehearsal distinct from a formation meeting and flag any steps waiting on establishment. Check who would record a later appointment or filing and where the receipt belongs.\n\nKeep the status of each AGM or formation step, responsible officer and source to check in the authorised record.","captureNotes":"Walk through AGM preparation with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the status of each AGM or formation step, responsible officer and source to check using invented details. Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The AGM desk shows a rehearsal date and a prospective Treasurer. What does it establish?","choices":[{"id":"a","text":"A plan requiring verification of its governing process, people and notices before any formal step."},{"id":"b","text":"An AGM notice and election record once both fields are filled in."}],"correct_choice_id":"a","explanation":"The operating record needs the status of each AGM or formation step, responsible officer and source to check. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"an election plan with no evidence the process is applicable"},{"id":"b","text":"the status of each AGM or formation step, responsible officer and source to check"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Manage membership, renewals and member packs","body":"Check the current available joining or interest route and keep application, contact preferences, fee or payment check and approval distinct. Confirm the current status of classes, numbers, welcome packs, renewal or return planning, and actual links for prospective members. Route financial matters to the Treasurer and youth checks to the approved safeguarding role. Record restricted member corrections in the proper record. Keep formal actions within actual enabled authority.\n\nKeep the authorised membership state, evidence, owner and remaining queries in the authorised record.","captureNotes":"Walk through Membership and volunteer applications with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the authorised membership state, evidence, owner and remaining queries using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An interest form suggests a person is ready to join a class with fees still proposed. What do you record?","choices":[{"id":"a","text":"Record paid membership and reserve the supposed class fee for later."},{"id":"b","text":"Their enquiry status and the specific approved pathway or decision still needed."}],"correct_choice_id":"b","explanation":"The operating record needs the authorised membership state, evidence, owner and remaining queries. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the authorised membership state, evidence, owner and remaining queries"},{"id":"b","text":"a list of interested people labelled approved members"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Manage correspondence, safeguarded issues and message delivery","body":"Triage new correspondence to a reply, official decision, operational work or restricted concern. Keep private attachments in approved storage, pass safety issues to the authorised contact and give the committee only the needed reference. Check the newsletter, member notices, optional opt-in and birthdays, message queue and delivery permissions. Distinguish draft, authorised release and confirmed delivery and advise the responsible officer about missed messages.\n\nKeep the responsible contact, consent and actual delivery state or restricted reference in the authorised record.","captureNotes":"Walk through Committee notices and Email awaiting delivery with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the responsible contact, consent and actual delivery state or restricted reference using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A draft message queue item includes identifying details about a safeguarding concern. What should you do?","choices":[{"id":"a","text":"Move the concern to the authorised restricted route and keep only the necessary task reference in shared work."},{"id":"b","text":"Send it to all officers so delivery can be confirmed in one place."}],"correct_choice_id":"a","explanation":"The operating record needs the responsible contact, consent and actual delivery state or restricted reference. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"a general message printout containing private case details"},{"id":"b","text":"the responsible contact, consent and actual delivery state or restricted reference"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Coordinate the monthly Social Studio and partner records","body":"Review the existing monthly plan and underlying events. Import or link dates using the current recognised source, check proposed versus confirmed status, and review which officer approved each public update. Record revisions and actual links when published. For partner requests give the committee and operator evidence of scope, ownership, written acceptance and review. Classify agreements and private contact records correctly in Documents.\n\nKeep the source event, approved revision and release record, or a named blocked action in the authorised record.","captureNotes":"Walk through Social Studio and Ready SETCO requests with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the source event, approved revision and release record, or a named blocked action using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The social plan has an unconfirmed date and someone marks it ready. What do you do?","choices":[{"id":"a","text":"Publish on the planned day and mark the source as the social calendar."},{"id":"b","text":"Refer the date to the responsible event owner, preserve the revision and record the actual approval state."}],"correct_choice_id":"b","explanation":"The operating record needs the source event, approved revision and release record, or a named blocked action. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the source event, approved revision and release record, or a named blocked action"},{"id":"b","text":"a batch plan with checked boxes and no confirming source"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Prepare the Secretary’s handover and unresolved actions","body":"Provide authorised references for rules, minutes, decisions, formal checkpoints, membership, message queue and controlled documents. Give the next person a schedule for the next notice, nominations, any filing, event and private requests. Mark what needs authority, what the Assistant Secretary can cover and what is limited to other roles. Verify access and agree a first-week review of missing evidence and due dates.\n\nKeep the current records index, cover and deadlines with restricted references in the authorised record.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the current records index, cover and deadlines with restricted references using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A member correction is overdue but belongs in a protected desk. What do you hand over?","choices":[{"id":"a","text":"The authorised record reference, owner, deadline and private access or escalation route."},{"id":"b","text":"A copy of the corrected personal record in a general handover email."}],"correct_choice_id":"a","explanation":"The operating record needs the current records index, cover and deadlines with restricted references. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a download of all files without access scope or priorities"},{"id":"b","text":"the current records index, cover and deadlines with restricted references"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Using fictional records, produce a Secretary’s file with a versioned rules proposal, notice and recipient log, agenda and reviewed minutes, nomination and follow-up checklist, and one member or volunteer case with privacy and approval boundaries. Include a newsletter release plan and an indexed handover. Mark which work is formation preparation and which needs future authority. Pass when the next Secretary can verify each action and no proposed decision, message or applicant is recorded as formally approved.',
  edit_version=edit_version+1
WHERE course_id='sandy-secretary' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Find the proposed sport, film, places and training pages and choose what to help shape.',
  lessons_json=json_array(
    json('{"title":"Tour the proposed programme","body":"Start with the programme and places pages. Compare sports, outdoor film and possible facilities. Mark which items are proposals, examples or open for a conversation.","captureNotes":"Capture the public programme and places pages. Use visual labels for proposed and confirmed information. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Choose a way to help","body":"Use the interest page to offer a sport, skill, venue conversation or help with formation. Ask what is being planned and who needs to agree before promising a date or place."}'),
    json('{"title":"Explore the useful pages by goal","body":"Use Sport and programme pages for activities, Film Club for screenings and workshops, Places and Facilities for options, and Join to offer interest or skills. Check the stage and contact rather than treating a visual concept or budget example as an operating facility.","captureNotes":"Walk through Public navigation and site directory with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Read the clubhouse and proposal status","body":"Use the public or synthetic preview to see how the work is organised. Check which private roles and member routes the operator currently provides. A reserved seat or proposal in a planning desk does not show that the event or role has been formally agreed.","captureNotes":"Walk through Members, Committee and constitution preview with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Know which person to ask","body":"Use the organiser for activity timing, the project contact for founding or support, and the proper private route for a membership or access question. Ask for current confirmation of any booking or proposed event before travelling.","captureNotes":"Walk through Join, My Membership and public contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='sandy-site-tour' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Prepare a sport lead to design inclusive sessions, agree sites and coaching, coordinate officials and equipment, manage changes, and verify results and handover.',
  lessons_json=json_array(
    json('{"title":"Define the sport pathway and people it serves","body":"Choose a proposed sport and the skills, audience, purpose and space it needs. Build a sequence from a beginner introduction to further practice, with roles for coaches, officials and volunteers. Check inclusion and accessible options with participants and how the three towns would use the programme. Name who can verify coaching or officiating requirements and confirm what is a concept or an agreed activity.\n\nKeep the audience, skill pathway, coach or official and planned approved dates in the authorised record.","captureNotes":"Walk through Sports and coaching calendar with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the audience, skill pathway, coach or official and planned approved dates using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A mixed-level session is advertised as beginner-friendly without a beginner plan. What changes?","choices":[{"id":"a","text":"Keep one standard session so no adjustments need to be recorded."},{"id":"b","text":"Define the supported starting activity, coach and accessible adjustments before publication."}],"correct_choice_id":"b","explanation":"The operating record needs the audience, skill pathway, coach or official and planned approved dates. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the audience, skill pathway, coach or official and planned approved dates"},{"id":"b","text":"a list of sport names with no teaching or support roles"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Confirm venue, equipment and costs","body":"Discuss footprint, access and equipment with the site and facilities owners. Record trip hazards, storage, setup space, availability, transport and a backup. Check the custody and condition of kit and what maintenance or costs someone will approve. Use a proposal until a site owner has agreed the actual time, purpose and conditions. Pass budget items and quotes to the Treasurer before commitments.\n\nKeep the site conditions, gear status, costs and decision date in the authorised record.","captureNotes":"Walk through Venue, court and screen bookings with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the site conditions, gear status, costs and decision date using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The court dimensions fit but a site owner has not agreed the proposed date. What should the lead record?","choices":[{"id":"a","text":"A suitable option awaiting consent and who will verify the conditions and backup."},{"id":"b","text":"An available booking once the site drawing is checked."}],"correct_choice_id":"a","explanation":"The operating record needs the site conditions, gear status, costs and decision date. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"a venue name and estimate without permission"},{"id":"b","text":"the site conditions, gear status, costs and decision date"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Rehearse the briefing and safeguarding process","body":"Assign the session lead, backup, coach or official, first-aid or welfare support and responsible check-in. Identify what supervision or youth and permission checks apply with the safeguarding lead. Rehearse check-in and pickup, including a missing guardian or change of role. Agree the designated private route for concerns and who can stop an activity. Use current official safeguarding guidance where the role requires it.\n\nKeep the supervision and roster approval, escalation route and fallback coverage in the authorised record.","captureNotes":"Walk through Volunteers and event roles with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the supervision and roster approval, escalation route and fallback coverage using invented details. Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A helper wants to supervise juniors before the agreed check is confirmed. What do you do?","choices":[{"id":"a","text":"Put another helper alongside them and check afterwards."},{"id":"b","text":"Hold that assignment and use the authorised safeguarding process for the relevant checks."}],"correct_choice_id":"b","explanation":"The operating record needs the supervision and roster approval, escalation route and fallback coverage. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the supervision and roster approval, escalation route and fallback coverage"},{"id":"b","text":"a participant list with no safeguarding handover"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Run and change sessions safely","body":"Confirm the approved date, site, controls and people before opening. Walk the lead through terrain, weather or crowd changes and how to notify participants when the plan changes. Check that gear is suitable for the conditions and that organisers know what they can change. Record incidents or stopping decisions through the agreed route and check that closures, relocations or refunds go through appropriate owners.\n\nKeep the operational decision, source, time and confirmed update in the authorised record.","captureNotes":"Walk through Sport, film and community events with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the operational decision, source, time and confirmed update using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Conditions exceed what the run sheet allows. What action should the lead take?","choices":[{"id":"a","text":"Use the agreed pause or stop process and communicate a verified update through the named channels."},{"id":"b","text":"Ask participants to choose individually whether the official activity continues."}],"correct_choice_id":"a","explanation":"The operating record needs the operational decision, source, time and confirmed update. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"a generic weather note without a decision owner"},{"id":"b","text":"the operational decision, source, time and confirmed update"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Verify results, consent and public updates","body":"Use the rules agreed for the activity to record results, eligibility and any dispute before publishing. Check whether photos, names, sponsor acknowledgements or youth content may be shared. Ask the appropriate officer to verify the audience and final wording. Keep sensitive records private and document corrections, participant feedback and an agreed follow-up.\n\nKeep the result evidence, review, display permissions and correction process in the authorised record.","captureNotes":"Walk through Results, prizes and sponsors with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the result evidence, review, display permissions and correction process using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"An unofficial result appears in a draft with identifiable junior photos. What happens?","choices":[{"id":"a","text":"Publish without names because the images have already been selected."},{"id":"b","text":"Hold it until results, audience and permissions have been checked through the right roles."}],"correct_choice_id":"b","explanation":"The operating record needs the result evidence, review, display permissions and correction process. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the result evidence, review, display permissions and correction process"},{"id":"b","text":"an unreviewed screenshot of the leaderboard"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Review the programme and hand over","body":"At close confirm equipment return, faults, expenses, volunteer feedback and evidence of what changed. Log attendance or feedback with the agreed level of detail. Bring future coach, venue and budget decisions to the right group. Give the successor the programme version, contacts, duties not covered, unresolved safety or maintenance issues and a review date.\n\nKeep the programme version, outcomes and gear or authority exceptions with successors in the authorised record.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the programme version, outcomes and gear or authority exceptions with successors using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"One borrowed item was returned damaged and sessions restart next week. What do you leave?","choices":[{"id":"a","text":"The item and fault, custody record, follow-up owner and decision about next use."},{"id":"b","text":"A note that all items were returned and the programme can continue."}],"correct_choice_id":"a","explanation":"The operating record needs the programme version, outcomes and gear or authority exceptions with successors. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a calendar export with no equipment or owner notes"},{"id":"b","text":"the programme version, outcomes and gear or authority exceptions with successors"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Build a fictional come-and-try pack for one Sandy sport. Include the participant and coach pathway, site access and approval, supervision and safeguarding checks, equipment and budget, roster and change decision, and a results or feedback and handover record. Rehearse a changed venue or unmet safety check. Pass when each person and approval has an owner, the programme is workable for beginners and unresolved conditions are visible.',
  edit_version=edit_version+1
WHERE course_id='sandy-sport-lead' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Offer skills, time, equipment or another contribution to the proposed club.',
  lessons_json=json_array(
    json('{"title":"Choose a practical offer","body":"Find one activity, facility or project you could support. Identify the item, time or skill and what conditions come with it. Discuss the right next step with the project contact.","captureNotes":"Show the public interest and equipment wishes pages. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Agree how it may be recognised","body":"Ask who would receive or hold a resource, how it would be returned and what may be said publicly. Record what is offered separately from what has been accepted."}'),
    json('{"title":"Offer useful terms before accepting","body":"Describe the resource, skill, donation or loan and what changes or costs apply. Ask which actual organisation or person can agree to receive it and who will be responsible for use, storage, maintenance or return. Wait for written confirmation where appropriate.","captureNotes":"Walk through Supporter and equipment wishes pages with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Agree use and acknowledgement","body":"Decide who may use the offer, for how long and what name, logo or wording may be used on each channel. Ask how a renewal, condition or withdrawal will be handled. A wish, contribution and signed commitment have different evidence.","captureNotes":"Walk through Sponsors and supporters contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Check delivery and follow-up","body":"Keep the agreed reference, date, custody and named contact for deliveries or expenses. Tell the project how to reach you if plans change. Ask what they can report back and how to resolve damaged items or an incorrect public acknowledgement.","captureNotes":"Walk through Project and asset contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='sandy-supporter' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Build an accountable finance practice for the proposed club, including budgets, funding, expenditure, stock, pricing, fundraising and reporting.',
  lessons_json=json_array(
    json('{"title":"Identify the funds and decision authority","body":"Identify the actual operator and whom each offer, invoice or commitment belongs to. Use the confirmed decision and approved private records before referring to funds as club funds. Check who can open or manage accounts, approve spending, release prices or speak to funders. Record starting balances, restrictions and obligations. Keep planning estimates separate. Use individually authorised access and check the responsible records before transferring custody.\n\nKeep the operator, accounts or proposed custody and actual authority references in the authorised record.","captureNotes":"Walk through Shop, stock and prices with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the operator, accounts or proposed custody and actual authority references using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A proposed fundraising budget names a club bank account whose status is unclear. What should be recorded?","choices":[{"id":"a","text":"Treat the cash sheet as a record of money already held by the proposed club."},{"id":"b","text":"Keep the amounts in planning and get the account owner, intended recipient and authority verified first."}],"correct_choice_id":"b","explanation":"The operating record needs the operator, accounts or proposed custody and actual authority references. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"the operator, accounts or proposed custody and actual authority references"},{"id":"b","text":"an estimated balance without an identified legal holder"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Build budgets and verify funding conditions","body":"Prepare separate budgets for sport, film, venue equipment and recurring running costs where relevant. Show real quotes, dated estimates, taxes where relevant, contingencies and whether income is confirmed, restricted or pending. Ask which entity is eligible to apply, whether site rights or other approvals are needed and who will report. Record milestones and variation approvals for any agreed funding. Review cash flow and exposure before presenting a decision.\n\nKeep the distinct budgets, funding evidence, restrictions, exposure and allocation decision in the authorised record.","captureNotes":"Walk through Grant register with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the distinct budgets, funding evidence, restrictions, exposure and allocation decision using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Two proposals rely on the same possible sponsor funds. What belongs in the plans?","choices":[{"id":"a","text":"Identify shared and unconfirmed income, and compare cash needs and a decision on allocation."},{"id":"b","text":"Count the full sponsorship in both until one project needs to submit."}],"correct_choice_id":"a","explanation":"The operating record needs the distinct budgets, funding evidence, restrictions, exposure and allocation decision. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"a combined optimistic total with duplicated income"},{"id":"b","text":"the distinct budgets, funding evidence, restrictions, exposure and allocation decision"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Control payments, reimbursements and event takings","body":"Set the authorised approval and custody process before accepting receipts or expenses. Reconcile an approved float, count takings with the agreed people and retain receipts and deposits with dates and accountable roles. Check payee changes with an established source before paying. Track pending or disputed expenses and variations and give the committee the appropriate finance summary. For a rehearsal, use fictional data and do not turn on collection or payment arrangements.\n\nKeep the opening float, source receipts, deposit or custody and verified exception in the authorised record.","captureNotes":"Walk through Fundraising and collections with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the opening float, source receipts, deposit or custody and verified exception using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A fundraiser’s cash count is higher than its recorded takings. What should you do?","choices":[{"id":"a","text":"Add the difference to confirmed donations to balance the count."},{"id":"b","text":"Check float, sales and receipts, record the variance and assign an independent follow-up."}],"correct_choice_id":"b","explanation":"The operating record needs the opening float, source receipts, deposit or custody and verified exception. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the opening float, source receipts, deposit or custody and verified exception"},{"id":"b","text":"a single total with no variance record"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Run shop, prices and settlement checks","body":"Check the current owner and allowed stock desk actions. Separate an enquiry, order, collected sale and reconciled receipt. Check the evidence for any proposed public price and use the recorded price workflow with a different approver if an enabled workflow requires it. Verify the effective result and report rounding, refunds, shortages or discrepancies. Confirm fee and discount status with the authorised committee, keeping proposed prices and waived values separate from cash.\n\nKeep old and new price, approver, effective result and matching order or payment evidence in the authorised record.","captureNotes":"Walk through Shop, stock and prices with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include old and new price, approver, effective result and matching order or payment evidence using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"You requested a new public price and the approver has not reviewed it. What do you do?","choices":[{"id":"a","text":"Leave it pending and have another authorised reviewer verify it before it is treated as effective."},{"id":"b","text":"Publish the requested price because you already own the stock list."}],"correct_choice_id":"a","explanation":"The operating record needs old and new price, approver, effective result and matching order or payment evidence. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a price entered in a spreadsheet with no separate review"},{"id":"b","text":"old and new price, approver, effective result and matching order or payment evidence"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Track assets, loans and stock valuation","body":"Check recorded ownership and actual custody of sports and screen gear. Record serial or inventory references, condition, return dates, controls for lost items and any source cost. Take a physical count with the responsible custodian when applicable. Flag missing costs or commitments and distinguish equipment offered on loan from a donation or club asset. Report exposure, maintenance and authorised disposal or renewal decisions.\n\nKeep the asset or stock reference, ownership, costs, custody and unresolved condition in the authorised record.","captureNotes":"Walk through Club assets and loans with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the asset or stock reference, ownership, costs, custody and unresolved condition using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A returned speaker is damaged and its ownership was never settled. What belongs in the record?","choices":[{"id":"a","text":"Record it as written off to close the equipment return."},{"id":"b","text":"Flag the condition and unresolved ownership separately, contact the custodian and agree the next review."}],"correct_choice_id":"b","explanation":"The operating record needs the asset or stock reference, ownership, costs, custody and unresolved condition. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the asset or stock reference, ownership, costs, custody and unresolved condition"},{"id":"b","text":"an asset entry with an estimated value and no owner"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Report, review and prepare records for the AGM","body":"Reconcile actual figures to custody and statements where relevant. Provide budget versus actuals, funding restrictions, outstanding liabilities, stock and asset status, and unresolved evidence. Check the applicable reporting, year end and audit or review requirements with the operator and current Fair Trading guidance as matters become formal. Prepare the report and evidence list for the Chair and Secretary and record the committee decision, any correction and future dates.\n\nKeep the evidence-backed report, variances, applicable review and filing responsibility in the authorised record.","captureNotes":"Walk through Finance and AGM preparation with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the evidence-backed report, variances, applicable review and filing responsibility using invented details. Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A draft AGM report includes projected income as received. What should the Treasurer do?","choices":[{"id":"a","text":"Separate the forecast and actual position, verify the source and have the corrected report reviewed."},{"id":"b","text":"Leave the figures if the projected total is described as likely in the notes."}],"correct_choice_id":"a","explanation":"The operating record needs the evidence-backed report, variances, applicable review and filing responsibility. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a single forecast column labelled financial statements"},{"id":"b","text":"the evidence-backed report, variances, applicable review and filing responsibility"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Transfer finance and custody","body":"Provide the authorised record locations, reconciled balances, budgets, open costs, grant milestones, supporter terms, equipment custody and finance or storage access. Name who can approve ongoing transactions now, who owns pending applications and who must review later. Verify any access changes and actual transfer of property through the appropriate process. Agree a first-week reconciliation and a check for outstanding approvals.\n\nKeep the current finance index, custody, access and owner for each pending item in the authorised record.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the current finance index, custody, access and owner for each pending item using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A successor receives a versioned report but cannot find the receipt evidence. How do you close the gap?","choices":[{"id":"a","text":"Treat the report as complete because it has a checked version number."},{"id":"b","text":"Assign the source check to the responsible person and keep the item open until verified."}],"correct_choice_id":"b","explanation":"The operating record needs the current finance index, custody, access and owner for each pending item. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the current finance index, custody, access and owner for each pending item"},{"id":"b","text":"a summary report with no source or secure transfer evidence"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Use a fictional formation budget, fundraiser cash and a sponsor loan. Show the current decision authority, two reconciliations, a held payment, restricted grant and variance tracking, a priced stock item with its separate review, and a year-end or operator reporting plan. Hand over balances, evidence and unresolved obligations. Pass when funds and offers are classified accurately, exceptions are explained and each payment or claim has a traceable source and authority.',
  edit_version=edit_version+1
WHERE course_id='sandy-treasurer' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Provide documented deputy cover and coordinate work across proposed sports, film, venues, volunteers, partner requests and follow-up.',
  lessons_json=json_array(
    json('{"title":"Agree deputy cover and access","body":"Check the prospective role status and what authority has actually been recorded. Agree when you would cover the Chair and which decisions you can facilitate, recommend or refer. Read the actual meeting basis, agenda and possible conflicts before acting. Use your own approved access and check which member or safeguarded records your role can open.\n\nKeep the cover and role status, permitted actions and decision owners in the authorised record.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the cover and role status, permitted actions and decision owners using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The Chair asks you to run a discussion but a commitment is proposed during it. What do you check?","choices":[{"id":"a","text":"Check the scope of your cover and take the commitment through the current authorised decision process."},{"id":"b","text":"Assume the cover includes authority for every item discussed."}],"correct_choice_id":"a","explanation":"The operating record needs the cover and role status, permitted actions and decision owners. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"a calendar invitation with no delegation"},{"id":"b","text":"the cover and role status, permitted actions and decision owners"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Coordinate decisions and overdue work","body":"Use the notices and officer lists to check each action’s source, owner, due date and dependency. Reassign or offer to take a task through the agreed route. Confirm the completion evidence and check the underlying issue before archiving a linked notice. Take a stalled or overlapping decision to the Chair and Secretary with an actionable comparison.\n\nKeep the source, action status, blocked dependency and owner in the authorised record.","captureNotes":"Walk through Officer to-do lists with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the source, action status, blocked dependency and owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The owner finished a reminder but the dependency still blocks release. How should you report it?","choices":[{"id":"a","text":"Archive the notice as resolved because its reminder was completed."},{"id":"b","text":"Show the reminder done and leave the dependent decision open with its owner."}],"correct_choice_id":"b","explanation":"The operating record needs the source, action status, blocked dependency and owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"the source, action status, blocked dependency and owner"},{"id":"b","text":"a ticked list with no source decision"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Coordinate venue and equipment clashes","body":"Compare sport, film and other requests by dates, space, gear, accessibility, approved access and people needed. Record backup options and which decisions depend on site owners or equipment custodians. Put the alternatives and their consequences to the responsible group. Tell the leads the status and retain both requests until the clash is resolved.\n\nKeep the competing needs, responsible decision and backup plan in the authorised record.","captureNotes":"Walk through Venue, court and screen bookings with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the competing needs, responsible decision and backup plan using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The same proposed site is listed for a screening and beach sport. What moves it forward?","choices":[{"id":"a","text":"Compare dependencies and ask the responsible site and programme people to confirm an allocation."},{"id":"b","text":"Make the first booking definite in the calendar and ask the second group to move."}],"correct_choice_id":"a","explanation":"The operating record needs the competing needs, responsible decision and backup plan. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"two dates entered as confirmed in separate desks"},{"id":"b","text":"the competing needs, responsible decision and backup plan"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Follow through on volunteers and safe delivery","body":"Check roster coverage, training, agreed duties, responsible supervision, safeguarding verification and self-service arrangements with the lead. Confirm who can change or pause an event. Ask how to handle an urgent concern or unmet check. Record the authorised next action and do not circulate restricted case details. Discuss accessibility and participant communication before recommending a launch date.\n\nKeep the responsible roster, checks and who can change or stop the event in the authorised record.","captureNotes":"Walk through Volunteers and event roles with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the responsible roster, checks and who can change or stop the event using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A new helper volunteers for a task outside their agreed duties at a youth session. Who can make the change?","choices":[{"id":"a","text":"Give the duty provisionally and update the check after their first session."},{"id":"b","text":"Refer to the lead and current safeguarding process before treating the task as assigned."}],"correct_choice_id":"b","explanation":"The operating record needs the responsible roster, checks and who can change or stop the event. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the responsible roster, checks and who can change or stop the event"},{"id":"b","text":"a list of available people with no confirmed duties"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Keep partners, costs and programme status visible","body":"Check the scope being discussed, the actual operator, partner acceptance or enquiry status and where proposed costs belong. Record who would supply equipment, handling of takings and who confirms any expense. Separate volunteer help from a paid assignment. Explain the confirmed status to each lead and escalate any material commitment to the correct authority.\n\nKeep the exact offer, cost and authority status with follow-up owner in the authorised record.","captureNotes":"Walk through Ready SETCO requests with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the exact offer, cost and authority status with follow-up owner using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A partner says they can help and the event lead asks to include them in a funded bid. What should happen?","choices":[{"id":"a","text":"Check specific scope, costs and approval or acceptance before treating them as committed."},{"id":"b","text":"Include them as confirmed because a message says they can help."}],"correct_choice_id":"a","explanation":"The operating record needs the exact offer, cost and authority status with follow-up owner. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a partner name added to a draft budget"},{"id":"b","text":"the exact offer, cost and authority status with follow-up owner"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Support public updates and rescheduling","body":"Check the source calendar and whether the site, activity and public wording are confirmed. Use the authorised review path and record when an officer cleared the content. In a change, agree the message and affected channels with the event lead and Secretary. Verify old public listings are corrected and record the result.\n\nKeep the confirmed change, affected channels and who will verify the replacement in the authorised record.","captureNotes":"Walk through Committee notices and Social Studio with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the confirmed change, affected channels and who will verify the replacement using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"One venue cancels and a back-up is still under discussion. What can the public update say?","choices":[{"id":"a","text":"Send the proposed replacement venue as the new location to minimise disruption."},{"id":"b","text":"Announce the confirmed change and mark the alternative as pending until it is agreed."}],"correct_choice_id":"b","explanation":"The operating record needs the confirmed change, affected channels and who will verify the replacement. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the confirmed change, affected channels and who will verify the replacement"},{"id":"b","text":"a revised graphic with no decision or source"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Transfer the deputy’s live work","body":"Prepare the next programme, scope of cover, conflict items, owners, venue and equipment dependencies, private escalation contacts and unresolved partner messages. Record what belongs to the Chair, the individual leads and the prospective deputy. Verify access, return equipment if applicable and agree the date on which the incoming person will review unfinished tasks.\n\nKeep the deputy scope, cross-team dependencies and dated first review in the authorised record.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the deputy scope, cross-team dependencies and dated first review using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"Your successor can see the calendar but two leads are waiting for a decision. What do you transfer?","choices":[{"id":"a","text":"The actual clash and decision owner, responsible contacts and review date."},{"id":"b","text":"The calendar link and a note that leads will contact them if needed."}],"correct_choice_id":"a","explanation":"The operating record needs the deputy scope, cross-team dependencies and dated first review. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a copy of the programme with no accountability"},{"id":"b","text":"the deputy scope, cross-team dependencies and dated first review"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Give a fictional cover and coordination pack for a meeting, two competing venue requests and a proposed community event. Show the scope of delegation, how you would resolve an unowned task, approval and safeguarding gaps, a pause decision, a partner or gear dependency and the cleared next update. Pass when the chair and successor can see what the deputy may do, whose decision is needed and which real commitments are still open.',
  edit_version=edit_version+1
WHERE course_id='sandy-vice-president' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Practise checking in, working with a lead and handing over a proposed event shift.',
  lessons_json=json_array(
    json('{"title":"Ask about a real task","body":"Read the proposed role and say when you are available. Before treating a shift as agreed, confirm the lead, duties, meeting point, backup and equipment.","captureNotes":"Capture a fictional run sheet from an agreed demo or paper example. Reference site: https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Work within the briefing","body":"Ask who manages a weather or safety change. Check before taking over supervision, using gear or taking photos. Report concerns and hand back the equipment and unfinished actions."}'),
    json('{"title":"Check training, duties and youth arrangements","body":"Agree the exact task, lead, time, briefing, expenses and backup. Confirm whether any safety, screening, youth or equipment check applies and use the responsible contact. Ask what to do when a task changes before taking on unfamiliar work.","captureNotes":"Walk through Volunteer enquiry and event lead with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Confirm any meeting or filing procedures against the current adopted or proposed rules as applicable and current Queensland Fair Trading guidance. For child-related duties, check the designated safeguarding lead and current Queensland guidance."}'),
    json('{"title":"Work safely through changes","body":"Check the current venue, condition and who can stop or change the session. Use the agreed private route for a welfare or safeguarding concern. Clarify how the team will share verified changes, whom you should cover and which tasks you must leave to the authorised lead.","captureNotes":"Walk through Fictional or approved run sheet with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}'),
    json('{"title":"Return gear and leave a usable update","body":"Return equipment and record condition or faults. Pass on any remaining tasks, who owns them and the next check. Confirm who receives any expense or contribution record and give feedback or ask about future activity through the appropriate contact.","captureNotes":"Walk through Event lead and asset contact with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/"}')
  ),
  practical='',
  edit_version=edit_version+1
WHERE course_id='sandy-volunteer' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;

UPDATE learning_course_versions SET
  description='Run Sandy’s technical access, controlled release and recovery work while preserving the actual operator and the difference between role previews and permissions.',
  lessons_json=json_array(
    json('{"title":"Inventory systems, status and custodians","body":"Map the public site, website provider, repository, database, operator controls, email or media integrations, domain and record owners. Check which features are proposals, synthetic demos, enabled functions and closed formal approvals. Hold or route proposals for new integrations, publishing or paid services to the authorised decision-maker. Record renewal and backup responsibilities with an independent recovery contact.\n\nKeep the service and owner inventory, status, operator and open approval in the authorised record.","captureNotes":"Walk through Webmaster and External connections with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the service and owner inventory, status, operator and open approval using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A useful integration appears in the External connections desk. What makes it ready to enable?","choices":[{"id":"a","text":"A recorded authorised decision, scoped permissions, responsible people and tested safeguards."},{"id":"b","text":"The existence of a completed proposal form in the integration desk."}],"correct_choice_id":"a","explanation":"The operating record needs the service and owner inventory, status, operator and open approval. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"a URL list labelled active services"},{"id":"b","text":"the service and owner inventory, status, operator and open approval"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Reserve, invite, amend and revoke accounts","body":"Confirm the seat and actual authority before creating a reservation or preparing a private setup link. Check the intended person, link expiry and scope, record explicit authorisation and never distribute live credentials or preview access as if it were a real appointment. Track activation or expiration and test changes using individual accounts. Revoke or review departing access when directed and check the former privileges are denied.\n\nKeep the approved seat or scope, private invite status, expiry and verified change in the authorised record.","captureNotes":"Walk through Webmaster accounts with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the approved seat or scope, private invite status, expiry and verified change using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A prospective officer was reserved automatically and an organiser wants their setup link now. What happens?","choices":[{"id":"a","text":"Publish a shared activation link since the office already exists in the register."},{"id":"b","text":"Confirm the authorisation, intended person and scope before deliberately preparing the private link."}],"correct_choice_id":"b","explanation":"The operating record needs the approved seat or scope, private invite status, expiry and verified change. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"the approved seat or scope, private invite status, expiry and verified change"},{"id":"b","text":"a spreadsheet of raw invite links and account labels"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Test actual role boundaries","body":"Use the alternate navigation preview to understand layout and the view-only demo for synthetic records. Use separate authorised accounts and independent sessions to verify server permissions for committees, membership, finance, safeguarding and ordinary members. Check that restricted routes deny access, including after changes. Record environment, user role, observed outcome and the issue owner. Keep the formation or approval gates intact.\n\nKeep role-specific positive and denied checks in separate sessions in the authorised record.","captureNotes":"Walk through Webmaster role previews with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include role-specific positive and denied checks in separate sessions using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A Webmaster preview hides a finance link. Does that prove a regular committee member cannot reach finance records?","choices":[{"id":"a","text":"Verify with a separate actual test role and check the protected request is denied."},{"id":"b","text":"Treat the visible menu as proof of access control."}],"correct_choice_id":"a","explanation":"The operating record needs role-specific positive and denied checks in separate sessions. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which evidence belongs in the work record for this step?","choices":[{"id":"a","text":"a screenshot of the Webmaster''s preview navigation"},{"id":"b","text":"role-specific positive and denied checks in separate sessions"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Maintain safe release and dependency checks","body":"Review the requested change, authority, source, audience, memberships, permissions and project status. Stage a reproducible change, check links, key workflows and layout, then record who approved release and what went live. Verify the public URL and private areas separately. Save the rollback reference and check for exposed test data, drafts, private records or claims that opened gated activities prematurely.\n\nKeep the approved version, release checks, public result and rollback reference in the authorised record.","captureNotes":"Walk through Public site and Social Studio with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the approved version, release checks, public result and rollback reference using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A deployment succeeds and shows a public event still marked proposed by its lead. What next?","choices":[{"id":"a","text":"Leave it because the deployment was successful and the event is almost ready."},{"id":"b","text":"Verify the source decision and correct or roll back the inappropriate public status."}],"correct_choice_id":"b","explanation":"The operating record needs the approved version, release checks, public result and rollback reference. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would make this part of the handover usable?","choices":[{"id":"a","text":"the approved version, release checks, public result and rollback reference"},{"id":"b","text":"one live-page screenshot with no decision or scope"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Run support, privacy response and records care","body":"Classify reported issues and capture the minimum needed to act. Route membership status, finances and restricted safety decisions to their authorised officer. For a suspected exposure or lost account, use the agreed private incident path, contain affected access, keep limited evidence and record who reviews obligations and confirms closure. Avoid asking users to send passwords, live invitations or sensitive exports. Check support resolution through an authorised test.\n\nKeep the minimal incident or ticket reference, scope, owner and verified response in the authorised record.","captureNotes":"Walk through Webmaster support and Club documents with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the minimal incident or ticket reference, scope, owner and verified response using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A support ticket includes a copied private link. What should the Webmaster do?","choices":[{"id":"a","text":"Restrict it, follow the account or incident process and verify that the affected access is handled."},{"id":"b","text":"Forward the original message to all club officers for faster advice."}],"correct_choice_id":"a","explanation":"The operating record needs the minimal incident or ticket reference, scope, owner and verified response. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record would let an independent reviewer check the result?","choices":[{"id":"a","text":"a link or personal export in a shared work queue"},{"id":"b","text":"the minimal incident or ticket reference, scope, owner and verified response"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Confirm integrations, backups and recovery","body":"Verify actual decisions for hosted email, identity, pay services, media links or other processors before enabling them. Agree scope, service owner, deployment and runtime credential custody, costs and records. Back up agreed data and rehearse restoration with authorised test data. Check access and recent write history after recovery. Track outages, restore limits and how changes will be reviewed with the operator.\n\nKeep the approved provider or backup scope, recovery owner and test results in the authorised record.","captureNotes":"Walk through External connections and approvals with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the approved provider or backup scope, recovery owner and test results using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"A backup exists but has never been restored. What evidence is missing?","choices":[{"id":"a","text":"Proof that the backup file has the latest timestamp."},{"id":"b","text":"A recovery rehearsal with the expected records, permissions, steps and outcomes checked."}],"correct_choice_id":"b","explanation":"The operating record needs the approved provider or backup scope, recovery owner and test results. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"What would let the next person verify this work?","choices":[{"id":"a","text":"the approved provider or backup scope, recovery owner and test results"},{"id":"b","text":"a screenshot of a backup file listing"}],"correct_choice_id":"a","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}'),
    json('{"title":"Complete the technical handover","body":"Give the incoming operator a dated map of services, deployment records, open issues, access scopes, custody, renewals and test evidence. Have them demonstrate a safe release and where to find recovery material. Verify changes to outgoing access and review the timeline of scheduled work. Identify unresolved tasks and the decision-maker on each. Confirm a first-week session that checks actual authorised access.\n\nKeep the checked provider and recovery access, workflows, due dates and responsible contacts in the authorised record.","captureNotes":"Walk through Officer handover with an approved fictional case. Show the starting status, the responsible person, the action and what you check afterwards. Reference https://sandy-sports-club.auraofintelligence.workers.dev/ Include the checked provider and recovery access, workflows, due dates and responsible contacts using invented details.","questions":[{"id":"scenario-1","type":"single_choice","mode":"practice","prompt":"The incoming Webmaster can publish but cannot access the approved recovery route. What is the next step?","choices":[{"id":"a","text":"Record and resolve the approved access gap before closing the recovery handover."},{"id":"b","text":"Keep the previous account in use for every emergency."}],"correct_choice_id":"a","explanation":"The operating record needs the checked provider and recovery access, workflows, due dates and responsible contacts. This lets the next person verify the work and any remaining decision.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]},{"id":"scenario-2","type":"single_choice","mode":"practice","prompt":"Which record gives the incoming person enough evidence to follow up?","choices":[{"id":"a","text":"an administrator password and a list of browser favourites"},{"id":"b","text":"the checked provider and recovery access, workflows, due dates and responsible contacts"}],"correct_choice_id":"b","explanation":"The next person needs evidence they can check and an accurate account of the current status and follow-up.","source_refs":["https://sandy-sports-club.auraofintelligence.workers.dev/"]}]}')
  ),
  practical='Prepare a fictional controlled change and handover. Show an authorised reserved-seat invitation and expiry or revocation, separate real-role access tests with private paths denied where appropriate, a safe public release and rollback, one privacy or support escalation, and a restore rehearsal. Record provider and backup owners and pending integration decisions. Pass when the evidence distinguishes previews from actual access and the successor can verify, restore and hand over the service.',
  edit_version=edit_version+1
WHERE course_id='sandy-webmaster' AND revision=1 AND state='draft' AND edit_version=1 AND edited_by IS NULL;
